"use client";

import Link from "next/link";
import { usePathname } from "next/navigation";

const ENGINE_ROUTES = ["/engine-dashboard"];

export default function Header() {
  const pathname = usePathname();
  const isEngineTab = ENGINE_ROUTES.some((route) => pathname.startsWith(route));
  const activeTab = isEngineTab ? "engine" : "morpheme";

  return (
    <header className="h-[60px] bg-white border-b border-border-light flex items-center justify-between px-6 corporate-header-shadow z-20 shrink-0">
      <div className="flex items-center h-full gap-8">
        <div className="flex items-center">
          <h1 className="text-xl font-bold text-black tracking-tight">
            통합관리자
          </h1>
        </div>
        <div className="h-full flex items-center relative">
          <Link
            className={`h-full flex items-center px-4 text-[15px] transition-colors ${
              activeTab === "engine"
                ? "font-bold text-blue-600 relative after:content-[''] after:absolute after:bottom-0 after:left-0 after:w-full after:h-[3px] after:bg-blue-600"
                : "font-medium text-gray-500 hover:text-gray-800"
            }`}
            href="/engine-dashboard"
          >
            검색엔진 관리
          </Link>
          <Link
            className={`h-full flex items-center px-4 text-[15px] transition-colors ${
              activeTab === "morpheme"
                ? "font-bold text-blue-600 relative after:content-[''] after:absolute after:bottom-0 after:left-0 after:w-full after:h-[3px] after:bg-blue-600"
                : "font-medium text-gray-500 hover:text-gray-800"
            }`}
            href="/dashboard"
          >
            형태소 분석
          </Link>
        </div>
      </div>
      <div className="flex items-center gap-3">
        <button className="flex items-center gap-2 px-3 py-1.5 rounded border border-gray-200 bg-white hover:bg-gray-50 text-sm font-medium text-gray-700 transition-colors">
          <span className="material-symbols-outlined text-[20px] text-gray-400">
            person
          </span>
          통합검색개발팀_장민규
        </button>
      </div>
    </header>
  );
}

@import "tailwindcss";

@theme {
  --color-primary: #3b82f6;
  --color-corporate-blue: #0066ff;
  --color-background-light: #f5f6f8;
  --color-surface-light: #ffffff;
  --color-border-light: #e2e8f0;
  --color-text-primary: #111827;
  --color-text-secondary: #6b7280;

  --font-display: "Inter", "sans-serif";
}

@layer utilities {
  .corporate-header-shadow {
    box-shadow: 0 1px 2px 0 rgba(0, 0, 0, 0.05);
  }

  .term-card-shadow {
    box-shadow:
      0 10px 25px -5px rgba(0, 0, 0, 0.1),
      0 8px 10px -6px rgba(0, 0, 0, 0.1);
  }
}

@layer components {
  .nav-link-active {
    background-color: var(--color-blue-50);
    color: var(--color-blue-600);
    font-weight: 700;
    border-right-width: 4px;
    border-right-color: var(--color-blue-600);
  }

  .nav-link-inactive {
    color: var(--color-gray-600);
  }

  .nav-link-inactive:hover {
    background-color: var(--color-gray-50);
  }
}

body {
  font-family: var(--font-display);
  background-color: var(--color-background-light);
  color: var(--color-text-primary);
}

